export type TramiteCategory = 'salud' | 'educacion' | 'becas';

export interface TramiteStep {
  order: number;
  title: string;
  instruction: string;
  simpleExplanation: string;
}

export interface TramiteRecord {
  id: string;
  title: string;
  category: TramiteCategory;
  institution: string;
  summary: string;
  simpleSummary: string;
  requirements: string[];
  steps: TramiteStep[];
  cost: string;
  estimatedTime: string;
  officialChannel: string;
  keywords: string[];
  updatedAt: string;
}

export interface SearchResult {
  tramite: TramiteRecord;
  score: number;
  matchedTerms: string[];
  source: 'local-sqlite' | 'mesh-hop' | 'online-sync';
}

export type MeshPacketType = 'QUERY' | 'RESPONSE' | 'BEACON';

export interface MeshPacket {
  packetId: string;
  originId: string;
  senderId: string;
  type: MeshPacketType;
  ttl: number;
  hopCount: number;
  maxHops: number;
  timestamp: number;
  query?: string;
  payload?: string;
}

export interface MeshPeer {
  peerId: string;
  displayName: string;
  rssi: number;
  hasInternet: boolean;
  lastSeenAt: number;
  hopDistance: number;
}

export interface MeshStats {
  nodeId: string;
  isRunning: boolean;
  foregroundActive: boolean;
  packetsSent: number;
  packetsReceived: number;
  packetsRelayed: number;
  packetsDroppedDuplicate: number;
  packetsDroppedTtl: number;
  connectedPeers: number;
}

export interface VoiceGuideResponse {
  title: string;
  greeting: string;
  simpleAnswer: string;
  requirements: string[];
  steps: TramiteStep[];
  closingTip: string;
  source: 'gemini' | 'offline-local' | 'mesh-peer';
  modelUsed?: string;
  hopCount?: number;
}

export interface AppSettings {
  geminiApiKey: string;
  geminiModel: string;
  speechRate: number;
  largeTextMode: boolean;
  meshEnabled: boolean;
  maxHops: number;
}

import { SearchResult, TramiteCategory, TramiteRecord } from '../types/vozGuia';

const SPANISH_STOPWORDS = new Set([
  'el',
  'la',
  'los',
  'las',
  'un',
  'una',
  'unos',
  'unas',
  'de',
  'del',
  'al',
  'a',
  'en',
  'y',
  'o',
  'que',
  'como',
  'para',
  'por',
  'con',
  'sin',
  'sobre',
  'mi',
  'tu',
  'su',
  'me',
  'te',
  'se',
  'es',
  'son',
  'quiero',
  'necesito',
  'saber',
  'puedo',
  'hacer',
  'tramitar',
  'pedir',
  'informacion',
  'ayuda',
]);

export type SparseVector = Record<string, number>;

export function normalizeSpanishText(input: string): string {
  return input
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export function tokenizeSpanish(input: string): string[] {
  const normalized = normalizeSpanishText(input);
  if (!normalized) return [];
  const words = normalized.split(' ').filter((w) => w.length >= 2 && !SPANISH_STOPWORDS.has(w));
  const features: string[] = [];

  for (const word of words) {
    features.push(`w:${word}`);
    // Character 3-grams give resilience against typos and speech-to-text variations
    if (word.length >= 4) {
      for (let i = 0; i <= word.length - 3; i += 1) {
        features.push(`g:${word.slice(i, i + 3)}`);
      }
    }
  }
  return features;
}

export function buildTramiteSearchText(tramite: TramiteRecord): string {
  return [
    tramite.title,
    tramite.title,
    tramite.category,
    tramite.institution,
    tramite.summary,
    tramite.simpleSummary,
    ...tramite.keywords,
    ...tramite.keywords,
    ...tramite.requirements,
    ...tramite.steps.map((s) => `${s.title} ${s.simpleExplanation}`),
  ].join(' ');
}

export function buildNormalizedVector(text: string): SparseVector {
  const tokens = tokenizeSpanish(text);
  const counts: SparseVector = {};
  for (const token of tokens) {
    const weight = token.startsWith('w:') ? 2.0 : 0.65;
    counts[token] = (counts[token] ?? 0) + weight;
  }

  let normSquared = 0;
  for (const val of Object.values(counts)) {
    normSquared += val * val;
  }
  const norm = Math.sqrt(normSquared);
  if (norm === 0) return {};

  const normalized: SparseVector = {};
  for (const [key, val] of Object.entries(counts)) {
    normalized[key] = Number((val / norm).toFixed(6));
  }
  return normalized;
}

export function cosineSimilarity(a: SparseVector, b: SparseVector): number {
  let dot = 0;
  for (const [key, valA] of Object.entries(a)) {
    const valB = b[key];
    if (valB !== undefined) {
      dot += valA * valB;
    }
  }
  return Number(dot.toFixed(6));
}

export interface IndexedTramite {
  tramite: TramiteRecord;
  vector: SparseVector;
}

export function createVectorIndex(tramites: TramiteRecord[]): IndexedTramite[] {
  return tramites.map((tramite) => ({
    tramite,
    vector: buildNormalizedVector(buildTramiteSearchText(tramite)),
  }));
}

export function searchVectorIndex(
  index: IndexedTramite[],
  query: string,
  options?: { category?: TramiteCategory; limit?: number; minScore?: number }
): SearchResult[] {
  const limit = options?.limit ?? 5;
  const minScore = options?.minScore ?? 0.05;
  const filtered = options?.category
    ? index.filter((item) => item.tramite.category === options.category)
    : index;

  if (!query.trim()) {
    return filtered.slice(0, limit).map((item) => ({
      tramite: item.tramite,
      score: 1,
      matchedTerms: [],
      source: 'local-sqlite',
    }));
  }

  const queryVec = buildNormalizedVector(query);
  const queryWords = tokenizeSpanish(query).filter((t) => t.startsWith('w:'));

  const results: SearchResult[] = [];
  for (const item of filtered) {
    const score = cosineSimilarity(queryVec, item.vector);
    if (score >= minScore) {
      const matchedTerms = queryWords
        .filter((w) => item.vector[w] !== undefined)
        .map((w) => w.slice(2));
      results.push({
        tramite: item.tramite,
        score,
        matchedTerms,
        source: 'local-sqlite',
      });
    }
  }

  return results.sort((a, b) => b.score - a.score).slice(0, limit);
}

import { MeshPacket, MeshPacketType, MeshPeer, MeshStats } from '../types/vozGuia';

export type RoutingDecision =
  | { action: 'DROP_DUPLICATE'; packetId: string }
  | { action: 'DROP_TTL_EXPIRED'; packetId: string }
  | { action: 'DELIVER_LOCAL_AND_RELAY'; packet: MeshPacket; forwardPacket: MeshPacket }
  | { action: 'DELIVER_LOCAL_ONLY'; packet: MeshPacket };

export interface ControlledFloodingConfig {
  nodeId: string;
  defaultMaxHops?: number;
  seenCacheLimit?: number;
}

/**
 * Controlled Flooding Mesh Router for Voz Guía.
 * Enforces hop limits (TTL) and LRU packet deduplication to prevent BLE broadcast storms.
 */
export class ControlledFloodingRouter {
  private readonly nodeId: string;
  private readonly defaultMaxHops: number;
  private readonly seenCacheLimit: number;
  private readonly seenOrder: string[] = [];
  private readonly seenSet = new Set<string>();
  private readonly peers = new Map<string, MeshPeer>();

  private stats: MeshStats;

  constructor(config: ControlledFloodingConfig) {
    this.nodeId = config.nodeId;
    this.defaultMaxHops = config.defaultMaxHops ?? 4;
    this.seenCacheLimit = config.seenCacheLimit ?? 256;
    this.stats = {
      nodeId: this.nodeId,
      isRunning: false,
      foregroundActive: true,
      packetsSent: 0,
      packetsReceived: 0,
      packetsRelayed: 0,
      packetsDroppedDuplicate: 0,
      packetsDroppedTtl: 0,
      connectedPeers: 0,
    };
  }

  getNodeId(): string {
    return this.nodeId;
  }

  setRunning(isRunning: boolean, foregroundActive = true): void {
    this.stats.isRunning = isRunning;
    this.stats.foregroundActive = foregroundActive;
  }

  upsertPeer(peer: MeshPeer): void {
    this.peers.set(peer.peerId, peer);
    this.stats.connectedPeers = this.peers.size;
  }

  getPeers(): MeshPeer[] {
    return Array.from(this.peers.values()).sort((a, b) => b.rssi - a.rssi);
  }

  getStats(): MeshStats {
    return { ...this.stats, connectedPeers: this.peers.size };
  }

  createPacket(
    type: MeshPacketType,
    data: { query?: string; payload?: string; maxHops?: number }
  ): MeshPacket {
    const maxHops = data.maxHops ?? this.defaultMaxHops;
    const packetId = `${this.nodeId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const packet: MeshPacket = {
      packetId,
      originId: this.nodeId,
      senderId: this.nodeId,
      type,
      ttl: maxHops,
      hopCount: 0,
      maxHops,
      timestamp: Date.now(),
      query: data.query,
      payload: data.payload,
    };
    this.markSeen(packetId);
    this.stats.packetsSent += 1;
    return packet;
  }

  receivePacket(incoming: MeshPacket): RoutingDecision {
    this.stats.packetsReceived += 1;

    if (this.seenSet.has(incoming.packetId)) {
      this.stats.packetsDroppedDuplicate += 1;
      return { action: 'DROP_DUPLICATE', packetId: incoming.packetId };
    }

    this.markSeen(incoming.packetId);

    if (incoming.ttl <= 0) {
      this.stats.packetsDroppedTtl += 1;
      return { action: 'DROP_TTL_EXPIRED', packetId: incoming.packetId };
    }

    const delivered: MeshPacket = {
      ...incoming,
      hopCount: incoming.hopCount + 1,
    };

    const nextTtl = incoming.ttl - 1;
    if (nextTtl <= 0 || incoming.type === 'BEACON') {
      return { action: 'DELIVER_LOCAL_ONLY', packet: delivered };
    }

    const forwardPacket: MeshPacket = {
      ...delivered,
      senderId: this.nodeId,
      ttl: nextTtl,
    };

    this.stats.packetsRelayed += 1;
    return {
      action: 'DELIVER_LOCAL_AND_RELAY',
      packet: delivered,
      forwardPacket,
    };
  }

  private markSeen(packetId: string): void {
    if (this.seenSet.has(packetId)) return;
    this.seenSet.add(packetId);
    this.seenOrder.push(packetId);
    if (this.seenOrder.length > this.seenCacheLimit) {
      const oldest = this.seenOrder.shift();
      if (oldest) this.seenSet.delete(oldest);
    }
  }
}

