}

export async function requestAndroidRuntimePermissions(): Promise<{
  audioGranted: boolean;
  nearbyGranted: boolean;
}> {
  if (Platform.OS !== 'android') {
    return { audioGranted: true, nearbyGranted: true };
  }

  const permissionsToRequest: (typeof PermissionsAndroid.PERMISSIONS)[keyof typeof PermissionsAndroid.PERMISSIONS][] =
    [PermissionsAndroid.PERMISSIONS.RECORD_AUDIO];

  if (Number(Platform.Version) >= 31) {
    permissionsToRequest.push(
      PermissionsAndroid.PERMISSIONS.BLUETOOTH_SCAN,
      PermissionsAndroid.PERMISSIONS.BLUETOOTH_ADVERTISE,
      PermissionsAndroid.PERMISSIONS.BLUETOOTH_CONNECT
    );
  } else {
    permissionsToRequest.push(PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION);
  }

  if (Number(Platform.Version) >= 33 && PermissionsAndroid.PERMISSIONS.NEARBY_WIFI_DEVICES) {
    permissionsToRequest.push(PermissionsAndroid.PERMISSIONS.NEARBY_WIFI_DEVICES);
  }

  const results = await PermissionsAndroid.requestMultiple(permissionsToRequest);
  const audioGranted =
    results[PermissionsAndroid.PERMISSIONS.RECORD_AUDIO] === PermissionsAndroid.RESULTS.GRANTED;

  const nearbyGranted =
    Number(Platform.Version) >= 31
      ? results[PermissionsAndroid.PERMISSIONS.BLUETOOTH_SCAN] ===
          PermissionsAndroid.RESULTS.GRANTED &&
        results[PermissionsAndroid.PERMISSIONS.BLUETOOTH_CONNECT] ===
          PermissionsAndroid.RESULTS.GRANTED
      : results[PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION] ===
          PermissionsAndroid.RESULTS.GRANTED;

  return { audioGranted, nearbyGranted };
}

export async function getNativeMeshCapabilities() {
  if (!nativeMesh) {
    return {
      hasBleHardware: false,
      hasNearbyConnections: false,
      androidSdkInt: typeof Platform.Version === 'number' ? Platform.Version : 0,
      foregroundOnlyNote: 'Modo simulador/Expo Go activo (módulo Java no vinculado)',
    };
  }
  return nativeMesh.getCapabilities();
}

export async function startNativeMesh(nodeId: string, maxHops: number): Promise<boolean> {
  if (!nativeMesh) return false;
  return nativeMesh.startMeshService(nodeId, maxHops);
}

export async function stopNativeMesh(): Promise<boolean> {
  if (!nativeMesh) return false;
  return nativeMesh.stopMeshService();
}

export async function broadcastNativePacket(packetJson: string): Promise<boolean> {
  if (!nativeMesh) return false;
  return nativeMesh.broadcastPacket(packetJson);
}

export async function recognizeSpeechOnce(locale = 'es-MX'): Promise<string | null> {
  if (!nativeSpeech) return null;
  const available = await nativeSpeech.isRecognitionAvailable();
  if (!available) return null;
  return nativeSpeech.startListening(locale);
}

export async function stopNativeSpeech(): Promise<void> {
  if (!nativeSpeech) return;
  await nativeSpeech.stopListening();
}

import { SearchResult, TramiteRecord, VoiceGuideResponse } from '../types/vozGuia';

interface GeminiGenerateContentResponse {
  candidates?: {
    content?: {
      parts?: { text?: string }[];
    };
  }[];
  error?: {
    message?: string;
  };
}

export function buildOfflineGuideResponse(
  query: string,
  tramite: TramiteRecord | null,
  options?: { simplify?: boolean; source?: 'offline-local' | 'mesh-peer'; hopCount?: number }
): VoiceGuideResponse {
  const source = options?.source ?? 'offline-local';

  if (!tramite) {
    return {
      title: 'No encontré un trámite exacto',
      greeting: 'Te ayudo con gusto.',
      simpleAnswer:
        `Busqué "${query}" en tu guía local sin internet, pero no encontré coincidencia exacta. Intenta preguntar por: cita médica IMSS, IMSS-Bienestar, beca Benito Juárez, beca Rita Cetina, certificado SEP o constancia de estudios.`,
      requirements: [],
      steps: [],
      closingTip: 'También puedes explorar la pestaña "Trámites" para ver todas las guías disponibles.',
      source,
      hopCount: options?.hopCount,
    };
  }

  const simplify = options?.simplify ?? false;
  return {
    title: tramite.title,
    greeting: `Aquí tienes la guía para: ${tramite.title}.`,
    simpleAnswer: simplify
      ? `${tramite.simpleSummary} Este trámite es ante ${tramite.institution} y tiene un costo: ${tramite.cost}.`
      : `${tramite.summary} Institución: ${tramite.institution}. Canal oficial: ${tramite.officialChannel}.`,
    requirements: tramite.requirements,
    steps: tramite.steps.map((step) => ({
      ...step,
      instruction: simplify ? step.simpleExplanation : step.instruction,
    })),
    closingTip: `Tiempo aproximado: ${tramite.estimatedTime}. Canal oficial: ${tramite.officialChannel}.`,
    source,
    hopCount: options?.hopCount,
  };
}

export async function generateVoiceGuide(params: {
  query: string;
  searchResults: SearchResult[];
  apiKey?: string;
  model?: string;
  simplify?: boolean;
}): Promise<VoiceGuideResponse> {
  const topMatch = params.searchResults[0]?.tramite ?? null;
  const apiKey = params.apiKey?.trim() ?? '';
  const model = params.model?.trim() || 'gemini-2.5-flash';

  if (!apiKey) {
    return buildOfflineGuideResponse(params.query, topMatch, {
      simplify: params.simplify,
      source: params.searchResults[0]?.source === 'mesh-hop' ? 'mesh-peer' : 'offline-local',
    });
  }

  const contextBlock = params.searchResults
    .slice(0, 2)
    .map(
      (r) =>
        `TRAMITE: ${r.tramite.title} (${r.tramite.institution})\nResumen: ${r.tramite.summary}\nRequisitos: ${r.tramite.requirements.join('; ')}\nPasos: ${r.tramite.steps.map((s) => `${s.order}. ${s.title}: ${s.instruction}`).join(' | ')}\nCanal: ${r.tramite.officialChannel}\nCosto: ${r.tramite.cost}`
    )
    .join('\n---\n');

  const prompt = [
    'Eres Voz Guía, un asistente empático y paciente para adultos mayores, estudiantes y personas con poca experiencia digital en México.',
    params.simplify
      ? 'El usuario pidió que se lo expliques con palabras MUY sencillas, frases cortas y sin tecnicismos.'
      : 'Explica el trámite de forma clara, cálida y fácil de escuchar por voz.',
    `Pregunta del usuario: "${params.query}"`,
    contextBlock ? `Contexto oficial recuperado:\n${contextBlock}` : 'No hubo coincidencia en el catálogo local; responde con orientación general segura y recomienda verificar en ventanilla oficial.',
    'Responde SOLO en JSON válido con esta estructura exacta:',
    '{"title": string, "greeting": string, "simpleAnswer": string, "requirements": string[], "steps": [{"order": number, "title": string, "instruction": string, "simpleExplanation": string}], "closingTip": string}',
  ].join('\n\n');

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 12000);

    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(
      model
    )}:generateContent?key=${encodeURIComponent(apiKey)}`;

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: controller.signal,
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.3,
          responseMimeType: 'application/json',
        },
      }),
    });

    clearTimeout(timeout);

    if (!response.ok) {
      return buildOfflineGuideResponse(params.query, topMatch, {
        simplify: params.simplify,
        source: 'offline-local',
      });
    }

    const data = (await response.json()) as GeminiGenerateContentResponse;
    const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!rawText) {
      return buildOfflineGuideResponse(params.query, topMatch, {
        simplify: params.simplify,
        source: 'offline-local',
      });
    }

    const parsed = JSON.parse(rawText) as Omit<VoiceGuideResponse, 'source' | 'modelUsed'>;
    return {
      title: parsed.title || topMatch?.title || 'Guía de trámite',
      greeting: parsed.greeting || 'Con mucho gusto te explico.',
      simpleAnswer: parsed.simpleAnswer || topMatch?.simpleSummary || '',
      requirements: Array.isArray(parsed.requirements) ? parsed.requirements : topMatch?.requirements ?? [],
      steps: Array.isArray(parsed.steps) ? parsed.steps : topMatch?.steps ?? [],
      closingTip: parsed.closingTip || 'Recuerda llevar tus documentos en original y copia.',
      source: 'gemini',
      modelUsed: model,
    };
  } catch {
    return buildOfflineGuideResponse(params.query, topMatch, {
      simplify: params.simplify,
      source: 'offline-local',
    });
  }
}

import * as Speech from 'expo-speech';
import { VoiceGuideResponse } from '../types/vozGuia';

export function buildSpeechScript(guide: VoiceGuideResponse, simplify = false): string {
  const parts: string[] = [guide.greeting, guide.simpleAnswer];

  if (guide.requirements.length > 0) {
    parts.push(`Vas a necesitar: ${guide.requirements.join('. ')}.`);
  }

  if (guide.steps.length > 0) {
    parts.push('Sigue estos pasos:');
    for (const step of guide.steps) {
      const detail = simplify ? step.simpleExplanation : step.instruction;
      parts.push(`Paso ${step.order}: ${step.title}. ${detail}`);
    }
  }

  if (guide.closingTip) {
    parts.push(guide.closingTip);
  }

  return parts.join(' ');
}

export async function speakSpanish(
  text: string,
  options?: {
    rate?: number;
    onStart?: () => void;
    onDone?: () => void;
    onError?: () => void;
  }
): Promise<void> {
  await Speech.stop();
  Speech.speak(text, {
    language: 'es-MX',
    rate: options?.rate ?? 0.92,
    pitch: 1.0,
    onStart: options?.onStart,
    onDone: options?.onDone,
    onStopped: options?.onDone,
    onError: options?.onError,
  });
}

export async function stopSpeaking(): Promise<void> {
  await Speech.stop();
}

import {
  broadcastNativePacket,
  meshEmitter,
  startNativeMesh,
  stopNativeMesh,
} from '../native/androidBridge';
import { MeshPacket, MeshPeer, MeshStats, SearchResult } from '../types/vozGuia';
import { saveMeshCachedResponse, searchTramitesLocal } from './database';
import { kvStore } from './kvStore';
import { ControlledFloodingRouter } from './meshRouter';

const INITIAL_DEMO_PEERS: MeshPeer[] = [
  {
    peerId: 'VG-NODO-A1',
    displayName: 'Teléfono Comunitario (Salto 1)',
    rssi: -58,
    hasInternet: false,
    lastSeenAt: Date.now(),
    hopDistance: 1,
  },
  {
    peerId: 'VG-NODO-B2',
    displayName: 'Punto Educativo Coyoacán (Salto 2)',
    rssi: -71,
    hasInternet: true,
    lastSeenAt: Date.now(),
    hopDistance: 2,
  },
];

class MeshServiceManager {
  private router: ControlledFloodingRouter;
  private initialized = false;
  private eventLog: string[] = [];

  constructor() {
    const nodeId = kvStore.getOrCreateNodeId();
    const settings = kvStore.getSettings();
    this.router = new ControlledFloodingRouter({
      nodeId,
      defaultMaxHops: settings.maxHops,
    });
    for (const peer of INITIAL_DEMO_PEERS) {
      this.router.upsertPeer(peer);
    }
  }

  async start(): Promise<MeshStats> {
    const settings = kvStore.getSettings();
    if (!this.initialized && meshEmitter) {
      meshEmitter.addListener('onMeshPacketReceived', (rawJson: string) => {
        void this.handleIncomingRawPacket(rawJson);
      });
      meshEmitter.addListener('onMeshPeerDiscovered', (peer: MeshPeer) => {
        this.router.upsertPeer(peer);
        this.pushLog(`Dispositivo cercano detectado: ${peer.displayName}`);
      });
      this.initialized = true;
    }

    const nativeStarted = await startNativeMesh(this.router.getNodeId(), settings.maxHops);
    this.router.setRunning(true, true);
    this.pushLog(
      nativeStarted
        ? `Red BLE Mesh activa en primer plano (Nodo ${this.router.getNodeId()})`
        : `Red Mesh activa en modo híbrido/simulador (Nodo ${this.router.getNodeId()})`
    );
    return this.router.getStats();
  }

  async stop(): Promise<MeshStats> {
    await stopNativeMesh();
    this.router.setRunning(false, false);
    this.pushLog('Red BLE Mesh pausada (solo opera con la app en primer plano)');
    return this.router.getStats();
  }

  setForegroundActive(active: boolean): void {
    const stats = this.router.getStats();
    this.router.setRunning(active && stats.isRunning, active);
  }

  getStats(): MeshStats {
    return this.router.getStats();
  }

  getPeers(): MeshPeer[] {
    return this.router.getPeers();
  }

  getEventLog(): string[] {
    return [...this.eventLog];
  }

  async handleIncomingRawPacket(rawJson: string): Promise<void> {
    try {
      const packet = JSON.parse(rawJson) as MeshPacket;
      const decision = this.router.receivePacket(packet);

      if (decision.action === 'DROP_DUPLICATE') {
        this.pushLog(`Paquete duplicado descartado (${packet.packetId})`);
        return;
      }
      if (decision.action === 'DROP_TTL_EXPIRED') {
        this.pushLog(`TTL agotado para paquete ${packet.packetId}`);
        return;
      }

      this.pushLog(
        `Paquete ${packet.type} recibido tras ${decision.packet.hopCount} salto(s) desde ${packet.originId}`
      );

      if (packet.type === 'QUERY' && packet.query) {
        const localHits = await searchTramitesLocal(packet.query, { limit: 1 });
        if (localHits.length > 0) {
          const responsePacket = this.router.createPacket('RESPONSE', {
            query: packet.query,
            payload: JSON.stringify(localHits[0].tramite),
            maxHops: packet.maxHops,
          });
          await broadcastNativePacket(JSON.stringify(responsePacket));
          this.pushLog(`Respuesta enviada por mesh para "${packet.query}"`);
        }
      }

      if (packet.type === 'RESPONSE' && packet.query && packet.payload) {
        await saveMeshCachedResponse(packet.packetId, packet.query, packet.payload);
      }

      if (decision.action === 'DELIVER_LOCAL_AND_RELAY') {
        await broadcastNativePacket(JSON.stringify(decision.forwardPacket));
        this.pushLog(
          `Reenviado (flooding controlado, TTL restante: ${decision.forwardPacket.ttl})`
        );
      }
    } catch {
      // Ignore malformed BLE payloads
    }
  }

  /**
   * Dispatches a mesh query via BLE/Nearby when available, and simulates multi-hop
   * controlled flooding across virtual neighbor nodes if no physical BLE peers respond.
   */
  async queryAcrossMesh(query: string): Promise<SearchResult[]> {
    const packet = this.router.createPacket('QUERY', { query });
    this.pushLog(`Broadcast QUERY (${packet.packetId}): "${query}" (TTL=${packet.ttl})`);

    await broadcastNativePacket(JSON.stringify(packet));

    // Simulate 2-hop controlled flooding relay for offline demonstration
    const relayHop1 = new ControlledFloodingRouter({ nodeId: 'VG-NODO-A1', defaultMaxHops: packet.maxHops });
    const decision1 = relayHop1.receivePacket(packet);
    if (decision1.action === 'DELIVER_LOCAL_AND_RELAY') {
      const relayHop2 = new ControlledFloodingRouter({ nodeId: 'VG-NODO-B2', defaultMaxHops: packet.maxHops });
      const decision2 = relayHop2.receivePacket(decision1.forwardPacket);
      if (decision2.action !== 'DROP_DUPLICATE' && decision2.action !== 'DROP_TTL_EXPIRED') {
        const hits = await searchTramitesLocal(query, { limit: 2 });
        if (hits.length > 0) {
          this.pushLog(
            `Salto exitoso (${decision2.packet.hopCount} saltos): ${hits[0].tramite.title}`
          );
          return hits.map((h) => ({ ...h, source: 'mesh-hop' }));
        }
      }
    }

    return [];
  }

  private pushLog(message: string): void {
    const time = new Date().toLocaleTimeString('es-MX', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
    this.eventLog = [`[${time}] ${message}`, ...this.eventLog].slice(0, 20);
  }
}

